class Solution {
public:
    int colorTheGrid(int m, int n) {
        const int MOD = 1e9 + 7;
        vector<vector<int>> patterns;
        int total = 1;
        for (int i = 0; i < m; i++) total *= 3;
        for (int mask = 0; mask < total; mask++) {
            vector<int> col(m);
            int t = mask;
            bool valid = true;
            for (int i = 0; i < m; i++) {
                col[i] = t % 3;
                t /= 3;
                if (i > 0 && col[i] == col[i - 1]) { valid = false; break; }
            }
            if (valid) patterns.push_back(col);
        }
        int P = patterns.size();
        vector<vector<int>> compat(P);
        for (int i = 0; i < P; i++) {
            for (int j = 0; j < P; j++) {
                bool ok = true;
                for (int k = 0; k < m; k++) {
                    if (patterns[i][k] == patterns[j][k]) { ok = false; break; }
                }
                if (ok) compat[i].push_back(j);
            }
        }
        vector<long long> dp(P, 1);
        for (int col = 1; col < n; col++) {
            vector<long long> ndp(P, 0);
            for (int i = 0; i < P; i++) {
                if (dp[i] == 0) continue;
                for (int j : compat[i]) {
                    ndp[j] = (ndp[j] + dp[i]) % MOD;
                }
            }
            dp = ndp;
        }
        long long ans = 0;
        for (int i = 0; i < P; i++) ans = (ans + dp[i]) % MOD;
        return (int)ans;
    }
};
